ALTER TABLE classroom_messages ADD COLUMN file_name TEXT NOT NULL DEFAULT '', ADD COLUMN file_size BIGINT NOT NULL DEFAULT 0, ADD COLUMN media_type TEXT NOT NULL DEFAULT '', ADD COLUMN storage_key TEXT NOT NULL DEFAULT '', ADD COLUMN file_hash TEXT NOT NULL DEFAULT '';
ALTER TABLE classroom_messages DROP CONSTRAINT classroom_messages_body_check;
ALTER TABLE classroom_messages ADD CONSTRAINT classroom_messages_body_check CHECK(char_length(body)<=4000 AND (char_length(body)>0 OR file_name<>''));
CREATE TABLE classroom_messaging_policy(classroom_id UUID PRIMARY KEY REFERENCES classrooms(id) ON DELETE CASCADE, students_can_message BOOLEAN NOT NULL DEFAULT true, updated_by UUID REFERENCES users(id) ON DELETE SET NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE classroom_messaging_restrictions(classroom_id UUID REFERENCES classrooms(id) ON DELETE CASCADE,user_id UUID REFERENCES users(id) ON DELETE CASCADE,updated_by UUID REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(classroom_id,user_id));
CREATE TABLE classroom_message_themes(classroom_id UUID REFERENCES classrooms(id) ON DELETE CASCADE,user_id UUID REFERENCES users(id) ON DELETE CASCADE,theme TEXT NOT NULL CHECK(theme IN ('violet','lavender','ocean','sage','rose','midnight')),PRIMARY KEY(classroom_id,user_id));
CREATE TABLE conversation_message_themes(conversation_id UUID REFERENCES classroom_conversations(id) ON DELETE CASCADE,user_id UUID REFERENCES users(id) ON DELETE CASCADE,theme TEXT NOT NULL CHECK(theme IN ('violet','lavender','ocean','sage','rose','midnight')),PRIMARY KEY(conversation_id,user_id));
